import React, { useEffect, useState } from "react";
import PrescriptionOrdersTable from "./PrescriptionOrdersTable";

import useApi from "../../../hooks/useApi";
import { useNavigate, useParams } from "react-router-dom";
import departmentsApi from "../../../api/departmentsApi";
import { Loading } from "../../../components";
import { useStateContext } from "../../../contexts/ContextProvider";
import hospitalsApi from "../../../api/hospitals/hospitalsApi";

const columns = [

  { name: "Payment Method", uid: "payment_method_title" },
  { name: "Reference", uid: "reference_number" },
  { name: "Amount", uid: "amount" },
  { name: "Status", uid: "status" },
  { name: "Date", uid: "created" },
  { name: "Actions", uid: "actions" },
];

function PrescriptionOrderPaymentsList() {
  const [openDepartmentFormModal, setopenDepartmentFormModal] = useState(false);
  const [user, setUser] = useState();
  const navigate = useNavigate();
  const [selectedDepartment, setselectedDepartment] = useState();
  const [prescriptionOrderPayments, setprescriptionOrderPayments] = useState([]);
  const [data, setdata] = useState([]);
  const [modalTitle, setmodalTitle] = useState("");
  const [updated, setUpdated] = useState(false);

  const getPrescriptionOrderPaymentsActionsApi = useApi(hospitalsApi.hospitalStaffAction);

  const { loggedInUser } = useStateContext();

  const getPrescriptionOrderPayments  = async (data) => {
   
    await getPrescriptionOrderPaymentsActionsApi.request({
      action: "GetPrescriptionOrderPayments",
     
    });
  };

  useEffect(() => {
    if (getPrescriptionOrderPaymentsActionsApi.data) {
      if (getPrescriptionOrderPaymentsActionsApi.data.length) {
        setprescriptionOrderPayments(getPrescriptionOrderPaymentsActionsApi.data);
      }
    }
  }, [getPrescriptionOrderPaymentsActionsApi.data]);

  useEffect(() => {
    if (loggedInUser !== null && loggedInUser.entity_id !== null) {
      getPrescriptionOrderPayments(loggedInUser.entity_id);
    }

  }, []);

  useEffect(() => {
    setdata(prescriptionOrderPayments);
  }, [prescriptionOrderPayments]);

  const handleEditAction = (item) => {
    setopenDepartmentFormModal(true);
    setselectedDepartment(item);
    setmodalTitle(`Edit ${item.tittle}`);
  };

  const handleAddAction = () => {
    setopenDepartmentFormModal(true);
    setmodalTitle("Add new body system");
    setselectedDepartment(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/systems/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/systems/delete/${item.id}`);
  };

  useEffect(() => {
    if (getPrescriptionOrderPaymentsActionsApi.data && getPrescriptionOrderPaymentsActionsApi.data.length) {
      setprescriptionOrderPayments(getPrescriptionOrderPaymentsActionsApi.data);
    }
    console.log("getDepartmentsActionsApi.data", getPrescriptionOrderPaymentsActionsApi.data);
  }, [getPrescriptionOrderPaymentsActionsApi.data]);

  useEffect(() => {
    if (updated === true) {
      if (loggedInUser !== null && loggedInUser.entity_id !== null) {
        getPrescriptionOrderPayments(loggedInUser.entity_id);
      }
    }
  }, [updated]);

  //Filtering data
  useEffect(() => {
    setdata(prescriptionOrderPayments);
  }, [prescriptionOrderPayments]);

  const handleFilter = (e) => {
    const search_param = e;
    if (
      prescriptionOrderPayments &&
      prescriptionOrderPayments.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        prescriptionOrderPayments.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(prescriptionOrderPayments);
    }
  };

  return getPrescriptionOrderPaymentsActionsApi.loading ? (
    <Loading loading={departmentsApi.loading} />
  ) : (
    <div className="mt-16 md:mt-2">

      <PrescriptionOrdersTable
      title={"Pharmacy Payments"}
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>
  );
}

export default PrescriptionOrderPaymentsList;
